import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   double eps,
                                   double momentum,
                                   bool training);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void batchnorm2d_stats_kernel(
    const T* __restrict__ X,
    float* __restrict__ sum_out,
    float* __restrict__ sumsq_out,
    int N, int C, int H, int W)
{
    int c = blockIdx.y;
    int blockId = blockIdx.x;
    int numBlocks = gridDim.x;
    int HW = H * W;
    int64_t channel_stride = (int64_t)C * (int64_t)HW;
    const T* Xc = X + (int64_t)c * (int64_t)HW;
    int HW4 = HW / 4;
    int rem = HW - HW4 * 4;
    int64_t count4 = (int64_t)N * (int64_t)HW4;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    float lsum = 0.f, lsumsq = 0.f;
    for (int64_t idx = (int64_t)blockId * nthreads + tid; idx < count4; idx += (int64_t)numBlocks * nthreads) {
        int64_t n   = idx / HW4;
        int64_t hw4 = idx - n * HW4;
        const float4* ptr = reinterpret_cast<const float4*>(Xc + n * channel_stride + hw4 * 4);
        float4 v4 = *ptr;
        lsum   += v4.x + v4.y + v4.z + v4.w;
        lsumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }
    if (rem > 0) {
        int64_t tailCount = (int64_t)N * rem;
        for (int64_t idx = (int64_t)blockId * nthreads + tid; idx < tailCount; idx += (int64_t)numBlocks * nthreads) {
            int64_t n  = idx / rem;
            int64_t r  = idx - n * rem;
            int64_t hw = (int64_t)HW4 * 4 + r;
            float v = static_cast<float>(Xc[n * channel_stride + hw]);
            lsum   += v;
            lsumsq += v * v;
        }
    }
    unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        lsum   += __shfl_down_sync(mask, lsum, offset);
        lsumsq += __shfl_down_sync(mask, lsumsq, offset);
    }
    extern __shared__ float sdata[];
    int warpId = tid / warpSize;
    int laneId = tid % warpSize;
    int numWarps = (nthreads + warpSize - 1) / warpSize;
    float* ssum   = sdata;
    float* ssumsq = sdata + numWarps;
    if (laneId == 0) {
        ssum[warpId]   = lsum;
        ssumsq[warpId] = lsumsq;
    }
    __syncthreads();
    if (tid == 0) {
        float blockSum = 0.f, blockSumSq = 0.f;
        for (int i = 0; i < numWarps; ++i) {
            blockSum   += ssum[i];
            blockSumSq += ssumsq[i];
        }
        atomicAdd(&sum_out[c], blockSum);
        atomicAdd(&sumsq_out[c], blockSumSq);
    }
}
template <typename T>
__global__ void batchnorm2d_finalize_kernel(
    const float* __restrict__ sum_in,
    const float* __restrict__ sumsq_in,
    T* __restrict__ running_mean,
    T* __restrict__ running_var,
    float* __restrict__ mean_out,
    float* __restrict__ invstd_out,
    int N, int C, int H, int W,
    float eps, float momentum)
{
    int c = blockIdx.x;
    if (threadIdx.x != 0 || c >= C) return;
    int64_t count = (int64_t)N * (int64_t)H * (int64_t)W;
    float s  = sum_in[c];
    float sq = sumsq_in[c];
    float m   = s / (float)count;
    float var = sq / (float)count - m * m;
    if (var < 0.f) var = 0.f;
    float invstd = rsqrtf(var + eps);
    mean_out[c]   = m;
    invstd_out[c] = invstd;
    float unbiased_var = (count > 1) ? (var * (float)count / (float)(count - 1)) : var;
    running_mean[c] = (T)((1.0f - momentum) * (float)running_mean[c] + momentum * m);
    running_var[c]  = (T)((1.0f - momentum) * (float)running_var[c]  + momentum * unbiased_var);
}
template <typename T>
__global__ void batchnorm2d_normalize_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    const float* __restrict__ mean_arr,
    const float* __restrict__ invstd_arr,
    int N, int C, int H, int W)
{
    int c = blockIdx.y;
    int blockId = blockIdx.x;
    int numBlocks = gridDim.x;
    int HW = H * W;
    int64_t channel_stride = (int64_t)C * (int64_t)HW;
    const T* Xc = X + (int64_t)c * (int64_t)HW;
    T* Yc = Y + (int64_t)c * (int64_t)HW;
    int HW4 = HW / 4;
    int rem = HW - HW4 * 4;
    int64_t count4 = (int64_t)N * (int64_t)HW4;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    float mean   = mean_arr[c];
    float invstd = invstd_arr[c];
    float w = (weight != nullptr) ? static_cast<float>(weight[c]) : 1.0f;
    float b = (bias   != nullptr) ? static_cast<float>(bias[c])   : 0.0f;
    for (int64_t idx = (int64_t)blockId * nthreads + tid; idx < count4; idx += (int64_t)numBlocks * nthreads) {
        int64_t n   = idx / HW4;
        int64_t hw4 = idx - n * HW4;
        const float4* xptr = reinterpret_cast<const float4*>(Xc + n * channel_stride + hw4 * 4);
        float4* yptr = reinterpret_cast<float4*>(Yc + n * channel_stride + hw4 * 4);
        float4 v4 = *xptr;
        float4 y4;
        y4.x = (v4.x - mean) * invstd * w + b;
        y4.y = (v4.y - mean) * invstd * w + b;
        y4.z = (v4.z - mean) * invstd * w + b;
        y4.w = (v4.w - mean) * invstd * w + b;
        *yptr = y4;
    }
    if (rem > 0) {
        int64_t tailCount = (int64_t)N * rem;
        for (int64_t idx = (int64_t)blockId * nthreads + tid; idx < tailCount; idx += (int64_t)numBlocks * nthreads) {
            int64_t n  = idx / rem;
            int64_t r  = idx - n * rem;
            int64_t hw = (int64_t)HW4 * 4 + r;
            float v = static_cast<float>(Xc[n * channel_stride + hw]);
            float y = (v - mean) * invstd * w + b;
            Yc[n * channel_stride + hw] = static_cast<T>(y);
        }
    }
}
template <typename T>
__global__ void batchnorm2d_eval_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    const T* __restrict__ running_mean,
    const T* __restrict__ running_var,
    int N, int C, int H, int W,
    float eps)
{
    int c = blockIdx.y;
    int blockId = blockIdx.x;
    int numBlocks = gridDim.x;
    int HW = H * W;
    int64_t channel_stride = (int64_t)C * (int64_t)HW;
    const T* Xc = X + (int64_t)c * (int64_t)HW;
    T* Yc = Y + (int64_t)c * (int64_t)HW;
    int HW4 = HW / 4;
    int rem = HW - HW4 * 4;
    int64_t count4 = (int64_t)N * (int64_t)HW4;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    float mean = static_cast<float>(running_mean[c]);
    float var  = static_cast<float>(running_var[c]);
    float invstd = rsqrtf(var + eps);
    float w = (weight != nullptr) ? static_cast<float>(weight[c]) : 1.0f;
    float b = (bias   != nullptr) ? static_cast<float>(bias[c])   : 0.0f;
    for (int64_t idx = (int64_t)blockId * nthreads + tid; idx < count4; idx += (int64_t)numBlocks * nthreads) {
        int64_t n   = idx / HW4;
        int64_t hw4 = idx - n * HW4;
        const float4* xptr = reinterpret_cast<const float4*>(Xc + n * channel_stride + hw4 * 4);
        float4* yptr = reinterpret_cast<float4*>(Yc + n * channel_stride + hw4 * 4);
        float4 v4 = *xptr;
        float4 y4;
        y4.x = (v4.x - mean) * invstd * w + b;
        y4.y = (v4.y - mean) * invstd * w + b;
        y4.z = (v4.z - mean) * invstd * w + b;
        y4.w = (v4.w - mean) * invstd * w + b;
        *yptr = y4;
    }
    if (rem > 0) {
        int64_t tailCount = (int64_t)N * rem;
        for (int64_t idx = (int64_t)blockId * nthreads + tid; idx < tailCount; idx += (int64_t)numBlocks * nthreads) {
            int64_t n  = idx / rem;
            int64_t r  = idx - n * rem;
            int64_t hw = (int64_t)HW4 * 4 + r;
            float v = static_cast<float>(Xc[n * channel_stride + hw]);
            float y = (v - mean) * invstd * w + b;
            Yc[n * channel_stride + hw] = static_cast<T>(y);
        }
    }
}
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   double eps,
                                   double momentum,
                                   bool training) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();
    auto rm_c = running_mean.contiguous();
    auto rv_c = running_var.contiguous();
    int N = (int)x_c.size(0);
    int C = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int W = (int)x_c.size(3);
    TORCH_CHECK(w_c.size(0) == C, "weight size mismatch");
    TORCH_CHECK(b_c.size(0) == C, "bias size mismatch");
    TORCH_CHECK(rm_c.size(0) == C, "running_mean size mismatch");
    TORCH_CHECK(rv_c.size(0) == C, "running_var size mismatch");
    auto y = torch::empty_like(x_c);
    const int threads = 256;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (training) {
        // Split each channel's reduction/normalization across multiple blocks so that
        // the GPU's SMs are better utilized instead of launching only C blocks.
        const int blocksPerChannel = 32;
        dim3 grid(blocksPerChannel, C);
        dim3 block(threads);
        auto opts_f = x_c.options().dtype(at::kFloat);
        auto sum_t    = torch::zeros({C}, opts_f);
        auto sumsq_t  = torch::zeros({C}, opts_f);
        auto mean_t   = torch::empty({C}, opts_f);
        auto invstd_t = torch::empty({C}, opts_f);
        size_t shmem = 2 * ((threads + 31) / 32) * sizeof(float);
        batchnorm2d_stats_kernel<float><<<grid, block, shmem, stream>>>(
            x_c.data_ptr<float>(),
            sum_t.data_ptr<float>(),
            sumsq_t.data_ptr<float>(),
            N, C, H, W
        );
        int finThreads = 32;
        int finBlocks = C;
        batchnorm2d_finalize_kernel<float><<<finBlocks, finThreads, 0, stream>>>(
            sum_t.data_ptr<float>(),
            sumsq_t.data_ptr<float>(),
            rm_c.data_ptr<float>(),
            rv_c.data_ptr<float>(),
            mean_t.data_ptr<float>(),
            invstd_t.data_ptr<float>(),
            N, C, H, W,
            (float)eps, (float)momentum
        );
        batchnorm2d_normalize_kernel<float><<<grid, block, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_c.data_ptr<float>(),
            mean_t.data_ptr<float>(),
            invstd_t.data_ptr<float>(),
            N, C, H, W
        );
    } else {
        const int blocksPerChannel = 32;
        dim3 block(threads);
        dim3 grid(blocksPerChannel, C);
        batchnorm2d_eval_kernel<float><<<grid, block, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_c.data_ptr<float>(),
            rm_c.data_ptr<float>(),
            rv_c.data_ptr<float>(),
            N, C, H, W,
            (float)eps
        );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "batchnorm2d_kernel launch failed: ", cudaGetErrorString(err));
    if (training) {
        // Only copy back if the contiguous buffers are actually distinct storage.
        // Since running_mean/running_var are always contiguous buffers already,
        // rm_c/rv_c alias the same memory and the kernel already wrote results
        // directly into them; skipping the redundant copy_ avoids launching a
        // tiny, heavily underutilized elementwise kernel (grid_size=1) per call.
        if (running_mean.data_ptr() != rm_c.data_ptr()) {
            running_mean.copy_(rm_c);
        }
        if (running_var.data_ptr() != rv_c.data_ptr()) {
            running_var.copy_(rv_c);
        }
    }
    return y;
}
"""

bn_ext = load_inline(
    name="cute_batchnorm2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["batchnorm2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Batch Normalization implemented with a custom CUDA/CuTe kernel.
    """
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.num_batches_tracked = 0  # plain int counter: avoids launching a tiny, severely underutilized CUDA kernel per forward call

        self._ext = bn_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Avoid unnecessary full-tensor elementwise/copy kernels when the input
        # already satisfies the required device/dtype/layout constraints.
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float32:
            x = x.float()
        if not x.is_contiguous():
            x = x.contiguous()
        out = self._ext.batchnorm2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            float(self.eps),
            float(self.momentum),
            bool(self.training),
        )
        if self.training:
            self.num_batches_tracked += 1
        return out

