        int64_t tailCount = (int64_t)N * rem;
        for (int64_t idx = (int64_t)blockId * nthreads + tid; idx < tailCount; idx += (int64_t)numBlocks * nthreads) {
            int64_t n  = idx / rem;
            int64_t r  = idx - n * rem;
